		/** 
		 * Tests creating a new Obligation.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Obligation");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Obligation" );

			try {            
				Obligation entity = ObligationService.getObligationInstance().createObligation( generateNewEntity() );
				thePrimaryKey = entity.getObligationId();
				LOGGER.info( "-- Successfully created a Obligation with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Obligation. 
		 */
		public Obligation testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Obligation" );

			Obligation entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Obligation with primary key" );
			msg.append( thePrimaryKey );
			
			ObligationFetchOneSummary fetchOneSummary = new ObligationFetchOneSummary( thePrimaryKey );

			try {
				entity = ObligationService.getObligationInstance().getObligation( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Obligation " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Obligation.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Obligation." );

			StringBuilder msg = new StringBuilder( "Failed to update a Obligation : " );        
			Obligation entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Obligation." );

				// for use later on...
				thePrimaryKey = entity.getObligationId();

				ObligationService proxy = ObligationService.getObligationInstance();            
				proxy.updateObligation( entity );   

				LOGGER.info( "-- Successfully saved Obligation - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Obligation.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Obligation." );

			try{
			    Obligation entity = testRead(); 
				ObligationService.getObligationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Obligation with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Obligation with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Obligations.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Obligations:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Obligation : " );        
			List<Obligation> collection  = null;

			try {
				// call the static get method on the ObligationService
				collection = ObligationService.getObligationInstance().getAllObligation();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Obligation entity = null;            
					Iterator<Obligation> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getObligationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

